mapper.update:
update CHB_LOAN_DETAIL_INFO
set STATUS = #{status,jdbcType=VARCHAR}
where ASSET_UUID = #{assetUuid,jdbcType=CHAR}

mapper.select:
select sdl1.ITEM_CODE id,sdl1.ITEM_VALUE text from SYS_DATADICT_LIST sdl1 
inner join SYS_DATADICT_LIST_LINK sdll on sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl1.DICT_CODE = #{item_code_field}
and sdl1.ITEM_CODE=sdll.ITEM_CODE

	and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_child})



		sdl1.ITEM_VALUE like concat_ws('','%', #{search,jdbcType=VARCHAR},'%')
